(6447126, 957005, 83313, '<td valign="top">Since when is Andy Gibb a country singer? Might have been more effective had you left out the name of the artist.</td>', 'Since when is Andy Gibb a country singer? Might have been more effective had you left out the name of the artist.', '2011-06-19 01:56:55.000000', NULL, 1),
(6447132, 956883, 83313, '<td valign="top">Not coming up with any real song titles that have this name. Nice try. Interesting shot, and not overboard on the tonemapping.</td>', 'Not coming up with any real song titles that have this name. Nice try. Interesting shot, and not overboard on the tonemapping.', '2011-06-19 02:01:07.000000', NULL, 1),
(6447136, 957224, 83313, '<td valign="top">Nicely done and lit. Not terribly anonymous, though.</td>', 'Nicely done and lit. Not terribly anonymous, though.', '2011-06-19 02:05:26.000000', NULL, 1),
(6447137, 957263, 83313, '<td valign="top">Dampest looking fire I''ve ever seen.</td>', 'Dampest looking fire I''ve ever seen.', '2011-06-19 02:06:12.000000', NULL, 1),
